,YAAY,SACjD7D,EAAKqE,YAAcrE,EAAKqE,WAAWpE,eAAe,gBAAkBD,EAAKqE,WAAW,eACnF7E,IAAY,IAAMG,EAASL,KAAKQ,QAGlC,GAAIE,EAAKqE,YAAcrE,EAAKqE,WAAWpE,eAAe,gBAAkBD,EAAKqE,WAAW,cAAe,CACtGzE,EAAMS,UAAU,aAGjB0B,EAAEC,QAAQC,QAAQ,0BACjBvC,cAAeA,EACfoE,aAAc9D,EAAK8D,aACnBQ,UAAW9D,IAIb,SAAS4C,EAAa5C,GAErB,IAAI+D,EAAIC,OAAOC,MAAM,YACrBF,EAAEG,MAAQ,GACVH,EAAEI,QAAU,GACZC,WAAW,WACVpE,EAAMyB,QAAQsC,IACZ,KAGJ,SAASlB,EAAQ/D,EAAMM,GACtB,GAAIN,GAAQA,EAAKQ,OAAQ,CACxB,IAAK,IAAI+E,EAAI,EAAGA,EAAIvF,EAAKQ,SAAU+E,EAAG,CACrCjF,EAAMS,UAAU,MAAOf,EAAKuF,MAK/BvF,EAAKsB,QAAU,SAAU2C,GACxB,OAAOxB,EAAE,wBAA0BwB,EAAY,YAAYlD,UAAU,UAGtE,OAAOf","file":"node_modules/nodebb-plugin-composer-default/static/lib/composer/tags.js","sourcesContent":["
'use strict';

/* globals jQuery, ajaxify, define, config, socket, app, utils, $, window */

define('composer/tags', function () {
	var tags = {};

	var minTags;
	var maxTags;

	tags.init = function (postContainer, postData) {
		var tagEl = postContainer.find('.tags');
		if (!tagEl.length) {
			return;
		}

		minTags = ajaxify.data.hasOwnProperty('minTags') ? ajaxify.data.minTags : config.minimumTagsPerTopic;
		maxTags = ajaxify.data.hasOwnProperty('maxTags') ? ajaxify.data.maxTags : config.maximumTagsPerTopic;

		tagEl.tagsinput({
			confirmKeys: [13, 44],
			trimValue: true,
		});
		var input = postContainer.find('.bootstrap-tagsinput input');

		tagEl.on('beforeItemAdd', function (event) {
			var reachedMaxTags = maxTags && maxTags <= tags.getTags(postContainer.attr('data-uuid')).length;
			var cleanTag = utils.cleanUpTag(event.item, config.maximumTagLength);
			var different = cleanTag !== event.item;
			event.cancel = different ||
				event.item.length < config.minimumTagLength ||
				event.item.length > config.maximumTagLength ||
				reachedMaxTags;

			if (event.item.length < config.minimumTagLength) {
				return app.alertError('[[error:tag-too-short, ' + config.minimumTagLength + ']]');
			} else if (event.item.length > config.maximumTagLength) {
				return app.alertError('[[error:tag-too-long, ' + config.maximumTagLength + ']]');
			} else if (reachedMaxTags) {
				return app.alertError('[[error:too-many-tags, ' + maxTags + ']]');
			}
			if (different) {
				tagEl.tagsinput('add', cleanTag);
			}
		});

		tagEl.on('itemAdded', function (event) {
			var cid = postData.hasOwnProperty('cid') ? postData.cid : ajaxify.data.cid;
			socket.emit('topics.isTagAllowed', { tag: event.item, cid: cid || 0 }, function (err, allowed) {
				if (err) {
					return app.alertError(err.message);
				}
				if (!allowed) {
					return tagEl.tagsinput('remove', event.item);
				}
				$(window).trigger('action:tag.added', { cid: cid, tagEl: tagEl, tag: event.item });
				if (input.length) {
					input.autocomplete('close');
				}
			});
		});

		toggleTagInput(postContainer, postData, ajaxify.data);

		app.loadJQueryUI(function () {
			input.autocomplete({
				delay: 100,
				position: { my: 'left bottom', at: 'left top', collision: 'flip' },
				appendTo: postContainer.find('.bootstrap-tagsinput'),
				open: function () {
					$(this).autocomplete('widget').css('z-index', 20000);
				},
				source: function (request, response) {
					socket.emit('topics.autocompleteTags', {
						query: request.term,
						cid: postData.cid,
					}, function (err, tags) {
						if (err) {
							return app.alertError(err.message);
						}
						if (tags) {
							response(tags);
						}
						$('.ui-autocomplete a').attr('data-ajaxify', 'false');
					});
				},
				select: function (/* event, ui */) {
					// when autocomplete is selected from the dropdown simulate a enter key down to turn it into a tag
					triggerEnter(input);
				},
			});

			addTags(postData.tags, tagEl);
		});

		input.attr('tabIndex', tagEl.attr('tabIndex'));
		input.on('blur', function () {
			triggerEnter(input);
		});

		$('[component="composer/tag/dropdown"]').on('click', 'li', function () {
			var tag = $(this).attr('data-tag');
			if (tag) {
				addTags([tag], tagEl);
			}
			return false;
		});
	};

	tags.isEnoughTags = function (post_uuid) {
		return tags.getTags(post_uuid).length >= minTags;
	};

	tags.minTagCount = function () {
		return minTags;
	};

	tags.onChangeCategory = function (postContainer, postData, cid) {
		$.get(config.relative_path + '/api/category/' + cid, function (data) {
			var tagDropdown = postContainer.find('[component="composer/tag/dropdown"]');
			if (!tagDropdown.length) {
				return;
			}

			toggleTagInput(postContainer, postData, data);
			tagDropdown.toggleClass('hidden', !data.tagWhitelist || !data.tagWhitelist.length);
			if (data.tagWhitelist) {
				app.parseAndTranslate('composer', 'tagWhitelist', { tagWhitelist: data.tagWhitelist }, function (html) {
					tagDropdown.find('.dropdown-menu').html(html);
				});
			}
		});
	};

	function toggleTagInput(postContainer, postData, data) {
		var tagEl = postContainer.find('.tags');
		var input = postContainer.find('.bootstrap-tagsinput input');
		if (!input.length) {
			return;
		}

		if (data.hasOwnProperty('minTags')) {
			minTags = data.minTags;
		}
		if (data.hasOwnProperty('maxTags')) {
			maxTags = data.maxTags;
		}

		if (data.tagWhitelist && data.tagWhitelist.length) {
			input.attr('readonly', '');
			input.attr('placeholder', '');

			tagEl.tagsinput('items').slice().forEach(function (tag) {
				if (data.tagWhitelist.indexOf(tag) === -1) {
					tagEl.tagsinput('remove', tag);
				}
			});
		} else {
			input.removeAttr('readonly');
			input.attr('placeholder', postContainer.find('input.tags').attr('placeholder'));
		}

		postContainer.find('.tags-container').toggleClass('hidden', (
			data.privileges && data.privileges.hasOwnProperty('topics:tag') && !data.privileges['topics:tag']) ||
			(maxTags === 0 && !postData.tags.length)
		);

		if (data.privileges && data.privileges.hasOwnProperty('topics:tag') && !data.privileges['topics:tag']) {
			tagEl.tagsinput('removeAll');
		}

		$(window).trigger('action:tag.toggleInput', {
			postContainer: postContainer,
			tagWhitelist: data.tagWhitelist,
			tagsInput: input,
		});
	}

	function triggerEnter(input) {
		// http://stackoverflow.com/a/3276819/583363
		var e = jQuery.Event('keypress');
		e.which = 13;
		e.keyCode = 13;
		setTimeout(function () {
			input.trigger(e);
		}, 100);
	}

	function addTags(tags, tagEl) {
		if (tags && tags.length) {
			for (var i = 0; i < tags.length; ++i) {
				tagEl.tagsinput('add', tags[i]);
			}
		}
	}

	tags.getTags = function (post_uuid) {
		return $('.composer[data-uuid="' + post_uuid + '"] .tags').tagsinput('items');
	};

	return tags;
});
"]}

'use strict';

const async = require('async');
const validator = require('validator');
const _ = require('lodash');

const db = require('../database');
const meta = require('../meta');
const categories = require('../categories');
const plugins = require('../plugins');
const utils = require('../utils');
const batch = require('../batch');
const cache = require('../cache');

module.exports = function (Topics) {
	Topics.createTags = async function (tags, tid, timestamp) {
		if (!Array.isArray(tags) || !tags.length) {
			return;
		}
		const result = await plugins.hooks.fire('filter:tags.filter', { tags: tags, tid: tid });
		tags = _.uniq(result.tags)
			.map(tag => utils.cleanUpTag(tag, meta.config.maximumTagLength))
			.filter(tag => tag && tag.length >= (meta.config.minimumTagLength || 3));

		tags = await filterCategoryTags(tags, tid);
		const cid = await Topics.getTopicField(tid, 'cid');
		const topicSets = tags.map(tag => `tag:${tag}:topics`).concat(
			tags.map(tag => `cid:${cid}:tag:${tag}:topics`)
		);
		await Promise.all([
			db.setAdd(`topic:${tid}:tags`, tags),
			db.sortedSetsAdd(topicSets, timestamp, tid),
		]);
		await Topics.updateCategoryTagsCount([cid], tags);
		await Promise.all(tags.map(tag => updateTagCount(tag)));
	};

	Topics.updateCategoryTagsCount = async function (cids, tags) {
		await Promise.all(cids.map(async (cid) => {
			const counts = await db.sortedSetsCard(
				tags.map(tag => `cid:${cid}:tag:${tag}:topics`)
			);
			const set = `cid:${cid}:tags`;

			const bulkAdd = tags.filter((tag, index) => counts[index] > 0)
				.map((tag, index) => [set, counts[index], tag]);

			const bulkRemove = tags.filter((tag, index) => counts[index] <= 0)
				.map(tag => [set, tag]);

			await Promise.all([
				db.sortedSetAddBulk(bulkAdd),
				db.sortedSetRemoveBulk(bulkRemove),
			]);
		}));

		await db.sortedSetsRemoveRangeByScore(
			cids.map(cid => `cid:${cid}:tags`), '-inf', 0
		);
	};

	Topics.validateTags = async function (tags, cid) {
		if (!Array.isArray(tags)) {
			throw new Error('[[error:invalid-data]]');
		}
		tags = _.uniq(tags);
		const categoryData = await categories.getCategoryFields(cid, ['minTags', 'maxTags']);
		if (tags.length < parseInt(categoryData.minTags, 10)) {
			throw new Error(`[[error:not-enough-tags, ${categoryData.minTags}]]`);
		} else if (tags.length > parseInt(categoryData.maxTags, 10)) {
			throw new Error(`[[error:too-many-tags, ${categoryData.maxTags}]]`);
		}
	};

	async function filterCategoryTags(tags, tid) {
		const cid = await Topics.getTopicField(tid, 'cid');
		const tagWhitelist = await categories.getTagWhitelist([cid]);
		if (!Array.isArray(tagWhitelist[0]) || !tagWhitelist[0].length) {
			return tags;
		}
		const whitelistSet = new Set(tagWhitelist[0]);
		return tags.filter(tag => whitelistSet.has(tag));
	}

	Topics.createEmptyTag = async function (tag) {
		if (!tag) {
			throw new Error('[[error:invalid-tag]]');
		}
		if (tag.length < (meta.config.minimumTagLength || 3)) {
			throw new Error('[[error:tag-too-short]]');
		}
		const isMember = await db.isSortedSetMember('tags:topic:count', tag);
		if (!isMember) {
			await db.sortedSetAdd('tags:topic:count', 0, tag);
			cache.del('tags:topic:count');
		}
	};

	Topics.updateTags = async function (data) {
		await async.eachSeries(data, async (tagData) => {
			await db.setObject(`tag:${tagData.value}`, {
